// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        vm.prank(address(0x1234));
        bool ok;
        try c.setL1BlockValues(1, 2, 3, bytes32(0), 4, bytes32(0), 5, 6) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Call should have reverted");
    }
}
